public class ErpAccountSyncJob implements Queueable {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach finalizer to handle logging and retries regardless of the outcome
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.add(new Account(
                Id = accId,
                Description = 'Synced to ERP'
            ));
        }

        // Perform all-or-nothing update. A DML exception here rolls back the transaction
        // and triggers the attached finalizer.
        update accountsToUpdate;
    }
}
