```apex
public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<SObject> sObjects) {
        super(sObjects);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjects) {
            return new Opportunities(sObjects);
        }
    }

    public override void onAfterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) this.records) {
            if (opp.StageName == 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        processFulfilment(qualifyingIds);
    }

    public override void onAfterUpdate() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) this.records) {
            Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);
            if (oldOpp != null && oldOpp.StageName != 'Closed Won' && opp.StageName == 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        processFulfilment(qualifyingIds);
    }

    private void processFulfilment(Set<Id> qualifyingIds) {
        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service = Application.Service.newInstance(IOpportunityFulfilmentService.class);
