public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public AccountsSelector() {
        // Every query runs in user mode via the selector's data access setting
        this.setDataAccess(fflib_SObjectSelector.DataAccess.USER_MODE);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        // Dynamic fields from the Credit_Review field set
        // FieldSet.getFields() returns List<Schema.FieldSetMember>, which must be mapped to SObjectField
        for (Schema.FieldSetMember member : SObjectType.Account.FieldSets.Credit_Review.getFields()) {
            fields.add(SObjectType.Account.getDescribe().fields.getMap().get(member.getFieldPath()));
        }

        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        // Get Account field names from the current selector
        List<String> accountFieldNames = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            accountFieldNames.add(field.getDescribe().getName());
        }

        // Get Contact field names from the ContactsSelector
        List<String> contactFieldNames = new List<String>();
        ContactsSelector contactSelector = new ContactsSelector();
        for (Schema.SObjectField field : contactSelector.getSObjectFieldList()) {
            contactFieldNames.add(field.getDescribe().getName());
        }

        // Construct query string. 
        // Since we are using Database.query, we must explicitly add WITH USER_MODE 
        // to satisfy the requirement that the platform enforces access.
        String query = 'SELECT ' + String.join(accountFieldNames, ',') + 
                       ', (SELECT ' + String.join(contactFieldNames, ',') + ' FROM Contacts) ' + 
                       'FROM Account WHERE Id IN :accountIds WITH USER_MODE';

        return (List<Account>) Database.query(query);
    }
}
