public class CaseEscalationService {

    public class EscalationException extends Exception {}

    /**
     * Escalates a set of cases based on the provided reason.
     * Sets Case IsEscalated to true, Priority to High, and creates a high priority Task for the case owner.
     * 
     * @param caseIds Set of Case IDs to evaluate for escalation.
     * @param reason The reason for escalation; must not be blank.
     * @throws EscalationException if the reason is blank.
     */
    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('Reason is required for case escalation.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        ICasesSelector selector = CasesSelector.newInstance();
        List<Case> cases = selector.selectById(caseIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Boolean hasWork = false;

        for (Case c : cases) {
            // Skip cases that are closed or already escalated
            if (c.Status == 'Closed' || c.IsEscalated) {
                continue;
            }

            // Update Case
            c.IsEscalated = true;
            c.Priority = 'High';
            uow.registerDirty(c);

            // Create Escalation Task
            Task task = new Task();
            task.Subject = 'Escalated: ' + reason;
            task.WhatId = c.Id;
            task.OwnerId = c.OwnerId;
            task.ActivityDate = Date.today().addDays(1);
            task.Priority = 'High';
            uow.registerNew(task);

            hasWork = true;
        }

        if (hasWork) {
            uow.commitWork();
        }
    }
}
