import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    _value;
    _options = [];
    @track activeIndex = 0;

    @api label;

    @api 
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = value || [];
        this.syncActiveIndex();
    }

    @api 
    get value() {
        return this._value;
    }

    set value(val) {
        this._value = val;
        this.syncActiveIndex();
    }

    /**
     * Syncs activeIndex to the selected value, or defaults to the first option.
     */
    syncActiveIndex() {
        if (!this._options || this._options.length === 0) {
            this.activeIndex = 0;
            return;
        }
        const index = this._options.findIndex(opt => opt.value === this._value);
        this.activeIndex = index !== -1 ? index : 0;
    }

    /**
     * Computed list for the template to ensure aria-selected and IDs are correctly derived.
     */
    get listOptions() {
        return this._options.map((opt, index) => ({
            ...opt,
            id: `option-${index}`,
            index: index,
            isSelected: opt.value === this._value ? 'true' : 'false'
        }));
    }

    /**
     * The ID of the currently focused/active option for aria-activedescendant.
     */
    get activeId() {
        return `option-${this.activeIndex}`;
    }

    handleKeyDown(event) {
        const { key } = event;
        let handled = false;

        switch (key) {
            case 'ArrowDown':
                if (this.activeIndex < this._options.length - 1) {
                    this.activeIndex++;
                    handled = true;
                }
                break;
            case 'ArrowUp':
                if (this.activeIndex > 0) {
                    this.activeIndex--;
                    handled = true;
                }
                break;
            case 'Home':
                this.activeIndex = 0;
                handled = true;
                break;
            case 'End':
                this.activeIndex = this._options.length - 1;
                handled = true;
                break;
            case 'Enter':
            case ' ':
                this.selectActive();
                handled = true;
                break;
        }

        if (handled) {
            event.preventDefault();
        }
    }

    handleOptionClick(event) {
        const index = parseInt(event.currentTarget.dataset.index, 10);
        this.activeIndex = index;
        this.handleSelection(this._options[index].value);
    }

    selectActive() {
        const activeOption = this._options[this.activeIndex];
        if (activeOption) {
            this.handleSelection(activeOption.value);
        }
    }

    handleSelection(newValue) {
        // Only dispatch event if the selection actually changes
        if (newValue !== this._value) {
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: newValue }
            }));
        }
    }
}
