/**
 * @description Service class to handle the creation of NPSP Household Accounts
 * and association of family members.
 */
public with sharing class HouseholdService {

    /**
     * Creates a single NPSP Household Account and associates a list of new contacts to it.
     * The first contact in the list is designated as the primary contact.
     * 
     * To ensure NPSP's automatic household naming logic is triggered and that only 
     * one Household Account is created, we leverage NPSP's automatic household 
     * creation: inserting a Contact without an AccountId triggers NPSP to create 
     * a Household Account, name it, and set the Contact as the primary.
     * 
     * @param members List of new Contact records to be added to the household.
     * @return The Id of the newly created Household Account.
     * @throws IllegalArgumentException if members list is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('The members list cannot be null or empty.');
        }

        // 1. Insert the primary contact (the first one in the list).
        // In NPSP, inserting a Contact without an AccountId automatically creates 
        // a Household Account (HH_Account), names it, and assigns the contact 
        // as the primary (One2OneContact).
        Contact primaryContact = members[0];
        insert primaryContact;

        // 2. Re-query the primary contact to retrieve the AccountId.
        // The AccountId is assigned by NPSP triggers during the insert and is not 
        // automatically reflected in the in-memory 'primaryContact' object.
        Contact queriedPrimary = [SELECT AccountId FROM Contact WHERE Id = :primaryContact.Id LIMIT 1];
        Id householdId = queriedPrimary.AccountId;

        // 3. Associate all remaining members with the same household account.
        // By assigning the AccountId before insertion, we prevent NPSP from 
        // creating additional household accounts for these contacts.
        if (members.size() > 1) {
            List<Contact> otherMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                members[i].AccountId = householdId;
                otherMembers.add(members[i]);
            }
            insert otherMembers;
        }

        return householdId;
    }
}
