public with sharing class TA_Case_RollupOpenCount implements 
    TriggerAction.AfterInsert, 
    TriggerAction.AfterUpdate, 
    TriggerAction.AfterDelete, 
    TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject sob : triggerNew) {
            Case c = (Case) sob;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        processRollup(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        Map<Id, SObject> oldMap = new Map<Id, SObject>(triggerOld);
        for (SObject sob : triggerNew) {
            Case c = (Case) sob;
            Case oldC = (Case) oldMap.get(c.Id);
            if (c.AccountId != oldC.AccountId || c.IsClosed != oldC.IsClosed) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
                if (oldC.AccountId != null) {
                    accountIds.add(oldC.AccountId);
                }
            }
        }
        processRollup(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject sob : triggerOld) {
            Case c = (Case) sob;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        processRollup(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject sob : triggerNew) {
            Case c = (Case) sob;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        processRollup(accountIds);
    }

    private void processRollup(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCaseCounts = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) cnt 
            FROM Case 
            WHERE AccountId IN :accountIds AND IsClosed = false 
            GROUP BY AccountId
        ]) {
            openCaseCounts.put((Id)ar.get('AccountId'), (Integer)ar.get('cnt'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.add(new Account(
                Id = accId, 
                FB_Open_Case_Count__c = openCaseCounts.containsKey(accId) ? openCaseCounts.get(accId) : 0
            ));
        }
        update accountsToUpdate;
    }
}
