/**
 * Singleton provider for Account data needed by Contact trigger actions.
 * Ensures exactly one query per trigger execution.
 */
public class TA_Contact_Queries {
    private static TA_Contact_Queries instance;
    public Map<Id, Account> accountsById;

    private TA_Contact_Queries() {
        this.accountsById = new Map<Id, Account>();
    }

    /**
     * Returns the singleton instance of the queries helper.
     */
    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action that loads the required Account data into the singleton.
     */
    public class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject sob : triggerNew) {
                Contact c = (Contact) sob;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            if (accountIds.isEmpty()) {
                return;
            }

            // Refresh the map on every execution to account for transaction-level DML changes.
            TA_Contact_Queries.getInstance().accountsById = new Map<Id, Account>([
                SELECT BillingStreet, BillingCity, BillingPostalCode, BillingCountry, AccountSource
                FROM Account
                WHERE Id IN :accountIds
            ]);
        }
    }
}
