/**
 * Action to default Contact LeadSource from Account AccountSource 
 * if the Contact's LeadSource is blank.
 */
public class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accounts = TA_Contact_Queries.getInstance().accountsById;

        for (SObject sob : triggerNew) {
            Contact c = (Contact) sob;

            if (c.AccountId != null && String.isBlank(c.LeadSource)) {
                Account acc = accounts.get(c.AccountId);
                if (acc != null) {
                    c.LeadSource = acc.AccountSource;
                }
            }
        }
    }
}
